        // Number of airdrop claims by distinct (fresh, non-blacklisted) claimants.
        // Once totalRemaining is fully handed out, the correct contract must have
        // finished the distribution; the mutant keeps growing totalRemaining and
        // never finishes.
        n = bound(n, 300000, 300050);

        for (uint256 i = 0; i < n; i++) {
            address claimer = address(uint160(i + 1));
            vm.prank(claimer);
            c.getTokens();
        }

        // Universal rule: after the airdrop has handed out all remaining tokens
        // (totalRemaining depleted), the distribution is finished.
        assertTrue(c.distributionFinished(), "distribution must finish once totalRemaining is exhausted");
    }
}

