contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function runTest(address spender, uint256 amt) public {
        require(spender != address(0) && spender != address(this));
        require(amt > 0);

        // acquire tokens via the airdrop so this contract holds a balance
        c.getTokens();
        require(amt <= c.balanceOf(address(this)));

        // approve spender, then spend the allowance once via transferFrom
        c.approve(spender, amt);
        c.transferFrom(address(this), spender, amt);

        // In P the allowance is decremented by amt, so it is now < amt.
        // In M the decrement is deleted, so allowance remains == amt.
        assert(c.allowance(address(this), spender) < amt);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address tokenHolder) public payable {
        require(tokenHolder == msg.sender);
        c.XBornID();
        assert(c.balanceOf(tokenHolder) == c.totalSupply() - c.totalRemaining());
    }
    receive() external payable {}
}
